    target=ROOT/'tools/literature/chromvar-use-reviews.json';assert not target.exists();audit=json.loads((ROOT/'build/literature-review/signac-runtime/chromvar-primary-role-audit-1/PRIMARY-USES.json').read_bytes());assert audit['papers_scanned']==250 and audit['catalogued_papers']==audit['mentioned_papers']==5 and {r['paper_id'] for r in audit['records']}==set(NOTES);current=json.loads((ROOT/'tools/literature/reviewed-uses.json').read_bytes());assert not any(r['tool_id']=='chromvar' for r in current['reviews']);draft=[]
